  (* [comment removed for export] *)

  Lemma schunk_eq_dec : forall x y : schunk, {x = y} + {x <> y}.
  Proof. intros [a b c] [a' b' c']. destruct (Z.eq_dec a a'), (Z.eq_dec b b'), (Z.eq_dec c c'); subst; try (left; reflexivity); right; congruence. Qed.

  (* [comment removed for export] *)
